        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, str.
        :return: The ciphertext, str.
        """
        ciphertext = ""
        key_index = 0
        for char in plaintext:
            if char.isalpha():
                if char.isupper():
                    shift = ord(self.key[key_index].lower()) - 97
                else:
                    shift = ord(self.key[key_index].lower()) - 65
                if char.isupper():
                    ciphertext += chr((ord(char) - 65 + shift) % 26 + 65)
                else:
                    ciphertext += chr((ord(char) - 97 + shift) % 26 + 97)
                key_index = (key_index + 1) % len(self.key)
            else:
                ciphertext += char
        return ciphertext

    def rail_fence_cipher(self, plain_text, rails):
        """
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, str.
        :return: The ciphertext, str.
        """
        if rails <= 1:
            return plain_text
        fence = [['\n' for _ in range(len(plain_text))] for _ in range(rails)]
        # Fill the fence
        row, direction = 0, 1
        for char in plain_text:
            fence[row][row] = char
            row += direction
            if row == 0 or row == rails - 1:
                direction *= -1
        # Create the ciphertext
        ciphertext = ''
        for row in range(rails):
            for col in range(len(plain_text)):
                if fence[row][col]!= '\n':
                    ciphertext += fence[row][col]
        return ciphertext

